// HUNT for a tenant with natively onboarded AWS audit logs. Not scored by SIM-CDR-030 and not satisfied by its collector records.
// Field names of the normalised cloud audit data are UNVERIFIED: cloud_provider and event_name follow this corpus's convention, not a schema read from a tenant.
dataset = cloud_audit_logs
| filter timestamp_diff(current_time(), _time, "SECOND") < 604800
| filter cloud_provider = "AWS" and event_name in ("CreateTrail", "UpdateTrail", "StopLogging", "DeleteTrail")
| fields _time, cloud_provider, event_name

// HUNT for a tenant with natively onboarded Google Cloud audit logs. Not scored by SIM-CDR-030 and not satisfied by its collector records.
// Field names of the normalised cloud audit data are UNVERIFIED: cloud_provider and event_name follow this corpus's convention, not a schema read from a tenant. Whether event_name holds the full method name on Google Cloud records is also unverified.
dataset = cloud_audit_logs
| filter timestamp_diff(current_time(), _time, "SECOND") < 604800
| filter cloud_provider = "GCP" and event_name in ("google.logging.v2.ConfigServiceV2.CreateSink", "google.logging.v2.ConfigServiceV2.UpdateSink", "google.logging.v2.ConfigServiceV2.DeleteSink", "google.logging.v2.ConfigServiceV2.UpdateBucket", "google.logging.v2.ConfigServiceV2.DeleteBucket", "storage.buckets.delete")
| fields _time, cloud_provider, event_name
